function Logo() { return <KazipoaBrand />; }
function Chip({ children, tone = "plain" }: { children: React.ReactNode; tone?: string }) { return <span className={`chip ${tone}`}>{children}</span>; }
function SectionLabel({ eyebrow, title, copy }: { eyebrow: string; title: string; copy?: string }) { return <div className="section-heading"><div><p className="eyebrow">{eyebrow}</p><h2>{title}</h2></div>{copy && <p className="section-copy">{copy}</p>}</div>; }
